const SQUARES = ["tag-1", "tag-4", "tag-2", "tag-4", "tag-1"];

const Component = () => {
  const ref = useCanvas((ctx, { color }) => {
    ctx.fillStyle = color("tag-1");
    ctx.fillRect(30, 40, 50, 50);
    ctx.save();
    ctx.fillStyle = color("tag-4");
    ctx.fillRect(95, 40, 50, 50);
    ctx.save();
    ctx.fillStyle = color("tag-2");
    ctx.fillRect(160, 40, 50, 50);
    ctx.restore();
    ctx.fillRect(225, 40, 50, 50);
    ctx.restore();
    ctx.fillRect(290, 40, 50, 50);
    SQUARES.forEach((_, index) => note(ctx, color, `${index + 1}`, 55 + index * 65, 110, "center"));
  }, []);

  return (
    <Demo>
      <div className="@container">
        <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
          <Stage canvasRef={ref} height={130} />
          <StackSteps
            steps={[
              ["1 绿色", "tag-1", 0],
              ["save() → 2 黄色", "tag-4", 1],
              ["save() → 3 蓝色", "tag-2", 2],
              ["restore() → 4 黄色", "tag-4", 1],
              ["restore() → 5 绿色", "tag-1", 0],
            ]}
          />
        </div>
      </div>
    </Demo>
  );
